import math
def control(obs):
    h=float(obs.get('hitch_deg',0)); m=obs.get('motion',{}); v=float(m.get('v_mps',0)); status=obs.get('status','')
    # Pull forward to unwind the hitch before resuming reverse.
    if abs(h)>12 or status=='PINNED':
        return (max(-22,min(22,-h*0.65)),0.55,0)
    lm=obs.get('local_map',{}); L=lm.get('left_rail',[]); R=lm.get('right_rail',[])
    def at(P,u):
        P=sorted(P,key=lambda p:p[0])
        if not P:return None
        for a,b in zip(P,P[1:]):
            if a[0]<=u<=b[0]:
                q=(u-a[0])/(b[0]-a[0]); return a[1]+q*(b[1]-a[1])
        return min(P,key=lambda p:abs(p[0]-u))[1]
    vals=[]
    for u in (2,4,6):
        a,b=at(L,u),at(R,u)
        if a is not None and b is not None: vals.append((u,(a+b)/2))
    lat=vals[0][1] if vals else 0
    slope=(vals[-1][1]-vals[0][1])/(vals[-1][0]-vals[0][0]) if len(vals)>1 else 0
    # Route curve left: target its centerline; reverse steering responds opposite.
    steer=max(-24,min(24,-math.degrees(math.atan(slope))*1.2-lat*4+h*0.45))
    return (steer,-0.38,180)

