import math
phase = 'forward'
def control(obs):
    global phase
    h = float(obs.get('hitch_deg', 0.0))
    status = obs.get('status', '')
    route = float(obs.get('route', {}).get('bearing_deg', 0.0))
    lm = obs.get('local_map', {})
    L, R = lm.get('left_rail', []), lm.get('right_rail', [])
    def at(points, u):
        if not points: return None
        points = sorted(points, key=lambda p: p[0])
        if u <= points[0][0]: return points[0][1]
        if u >= points[-1][0]: return points[-1][1]
        for a, b in zip(points, points[1:]):
            if a[0] <= u <= b[0]:
                q = (u-a[0])/(b[0]-a[0])
                return a[1] + q*(b[1]-a[1])
        return None
    mids = []
    for u in (2.0, 4.0, 6.0):
        a, b = at(L, u), at(R, u)
        if a is not None and b is not None: mids.append((u, (a+b)/2.0))
    lat = mids[0][1] if mids else 0.0
    if phase == 'reverse' and (status == 'PINNED' or abs(h) > 26): phase = 'forward'
    if phase == 'forward':
        if abs(h) < 5 and status != 'PINNED': phase = 'reverse'
        else: return (0.0, 0.8, 0)
    steer = max(-13.0, min(13.0, -0.55*route - 2.0*lat - 0.40*h))
    speed = -0.28 if abs(h) > 16 else -0.42
    return (steer, speed, 180)

